import{_ as e,a0 as r,w as l,s,I as o,x as i,a1 as a,A as u,ao as x}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse(`{"title":"沒有 Linux 和開源軟件的世界會變得怎麼樣 | LCTT x X-CMD","titleTemplate":false,"description":"沒有 Linux 和開源軟件的世界會變得怎麼樣 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"沒有 Linux 和開源軟件的世界會變得怎麼樣 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"沒有 Linux 和開源軟件的世界會變得怎麼樣 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151126 Linux Foundation Explains a 'World without Linux' and Open Source","title":"沒有 Linux 和開源軟件的世界會變得怎麼樣","tag":"201602","desc":""},"relativePath":"201602/20151126 Linux Foundation Explains a 'World without Linux' and Open Source.md","filePath":"[post].md"}`),p={name:"201602/20151126 Linux Foundation Explains a 'World without Linux' and Open Source.md"};function d(L,n,m,f,h,g){const t=r("Link");return l(),s("div",null,[n[25]||(n[25]=o("h1",{id:"沒有-linux-和開源軟件的世界會變得怎麼樣",tabindex:"-1"},[i("沒有 Linux 和開源軟件的世界會變得怎麼樣 "),o("a",{class:"header-anchor",href:"#沒有-linux-和開源軟件的世界會變得怎麼樣","aria-label":"Permalink to “沒有 Linux 和開源軟件的世界會變得怎麼樣”"},"​")],-1)),n[26]||(n[26]=o("blockquote",null,[o("p",null,"Linux 基金會針最近對人們關於 “沒有 Linux 的世界” 系列短片所提出的問題做了回應，解答了包括沒有 Linux 和其他的開源軟件的因特網會變得怎麼樣等問題。")],-1)),n[27]||(n[27]=o("p",null,[o("img",{src:"http://thevarguy.com/site-files/thevarguy.com/files/imagecache/medium_img/uploads/2015/11/hey_22.png",alt:""})],-1)),o("p",null,[n[2]||(n[2]=i("假如 Linux —— 這個開源的操作系統內核 —— 不曾出現過，我們現在的世界是否會是另一番景象。會不會沒有了因特網，或者沒有了電影？這些都是觀看 ",-1)),a(t,{href:"http://linuxfoundation.org/"},{default:u(()=>[...n[0]||(n[0]=[i("Linux 基金會",-1)])]),_:1}),n[3]||(n[3]=i(" 正在連續播出的 “",-1)),a(t,{href:"http://www.linuxfoundation.org/world-without-linux"},{default:u(()=>[...n[1]||(n[1]=[i("沒有 Linux 的世界",-1)])]),_:1}),n[4]||(n[4]=i("” 系列短片的觀眾提出來的問題。",-1))]),o("p",null,[n[8]||(n[8]=i("假如你錯過了觀看這些短片也不要緊，“",-1)),a(t,{href:"http://www.linuxfoundation.org/world-without-linux"},{default:u(()=>[...n[5]||(n[5]=[i("沒有 Linux 的世界",-1)])]),_:1}),n[9]||(n[9]=i("” 系列短片是一個搞笑短片的集合，裏邊描述了沒有了 Linux （或者説沒有開源軟件）的世界發生的事情。這些短片強調了 Linux 在 ",-1)),a(t,{href:"http://thevarguy.com/open-source-application-software-companies/new-linux-foundation-video-highlights-role-open-source-3d"},{default:u(()=>[...n[6]||(n[6]=[i("電影製作",-1)])]),_:1}),n[10]||(n[10]=i(" 以及 ",-1)),a(t,{href:"http://thevarguy.com/open-source-application-software-companies/100715/would-internet-exist-without-linux-yes-without-open-sourc"},{default:u(()=>[...n[7]||(n[7]=[i("因特網服務",-1)])]),_:1}),n[11]||(n[11]=i(" 中充當的角色。",-1))]),n[28]||(n[28]=x('<p>為了揭示該系列短片的一些主張、傾向和隱藏元素，Linux 基金會副主席 Jennifer Cloer 最近在 The VAR Guy 上回應了關於該短片的一些問題。以下是她的原話解答。</p><h3 id="最新一集短片-——-sam-和-annie-一起看電影。假如沒有-linux-我們現在的熒屏是不是也和短片中的一樣" tabindex="-1">最新一集短片 —— Sam 和 Annie 一起看電影。假如沒有 Linux，我們現在的熒屏是不是也和短片中的一樣？ <a class="header-anchor" href="#最新一集短片-——-sam-和-annie-一起看電影。假如沒有-linux-我們現在的熒屏是不是也和短片中的一樣" aria-label="Permalink to “最新一集短片 —— Sam 和 Annie 一起看電影。假如沒有 Linux，我們現在的熒屏是不是也和短片中的一樣？”">​</a></h3><p>在第 4 集劇情中，我們惡搞了一下電影 “阿凡達（Avatar）”。不管你喜歡還是討厭，現實中的 “阿凡達（Avatar）” 在熒屏上的效果還是讓人記憶深刻的。在沒有 Linux 的世界中，電影的效果就變得非常醜陋，但是我們並不知道它有多難看，因為那已經是最好的了。但實際上，“阿凡達（Avatar）” 是使用 Linux 來進行效果製作的。Weta 數碼使用了當時世界上最大的 Linux 集羣來給電影做效果渲染和 3D 建模。據報道，指環王（Lord of the Rings）、神奇四俠（Fantastic Four）和金剛（King Kong）等電影都用到了 Linux。我希望該短片能引起人們關注，因為它所做的這方面的工作還並不廣為人知。</p><h3 id="很多人對短片的原始劇情進行了批判-其中就包括-沒有-linux-將沒有因特網-的劇情的指責。你對此持什麼樣的看法" tabindex="-1">很多人對短片的原始劇情進行了批判，其中就包括“沒有 Linux 將沒有因特網”的劇情的指責。你對此持什麼樣的看法？ <a class="header-anchor" href="#很多人對短片的原始劇情進行了批判-其中就包括-沒有-linux-將沒有因特網-的劇情的指責。你對此持什麼樣的看法" aria-label="Permalink to “很多人對短片的原始劇情進行了批判，其中就包括“沒有 Linux 將沒有因特網”的劇情的指責。你對此持什麼樣的看法？”">​</a></h3><p>我們很喜歡人們在短片剛上映就進行激烈的辯論。該短片上映當天就超過了 100,000 的觀眾，這引起了人們對 Linux 在社會中扮演的角色以及對全世界的社區貢獻者和維護者的關注。當然了，沒有 Linux 的話，因特網也是會出現的，只是不會像當前我們所熟知的互聯網那麼成熟而已。每一個短片都對 Linux 在我們每天生活中扮演的角色進行了大膽且有趣的描述。我們希望，這些短片能夠把關於 Linux 的故事推廣到全世界的人的心裏去。</p><h3 id="為什麼-sam-和-annie-的那隻貓叫做-string" tabindex="-1">為什麼 Sam 和 Annie 的那隻貓叫做 String？ <a class="header-anchor" href="#為什麼-sam-和-annie-的那隻貓叫做-string" aria-label="Permalink to “為什麼 Sam 和 Annie 的那隻貓叫做 String？”">​</a></h3><p>該短片系列中沒有一處劇情是隨意的。仔細的觀看的話，你就會發現其中關於 Linux 和極客們的各種玩笑。小貓 String 是我們的 Linux.com 主編 Libby Clark 以弦理論（string theory）親自來命名的。在物理學裏，弦理論（string theory）是一個理論框架，它用一個叫做弦（String）的一維對象替換了粒子物理學中粒子狀的粒子。弦理論（string theory）描述了這些弦（String）如何在空間傳播以及相互影響。就像 Sam、Annie 和 String 在那個沒有 Linux 的世界裏的關係那樣。</p><h3 id="我們期待已久的下兩集是什麼樣的-特別是-最後那集什麼時候上映" tabindex="-1">我們期待已久的下兩集是什麼樣的，特別是，最後那集什麼時候上映？ <a class="header-anchor" href="#我們期待已久的下兩集是什麼樣的-特別是-最後那集什麼時候上映" aria-label="Permalink to “我們期待已久的下兩集是什麼樣的，特別是，最後那集什麼時候上映？”">​</a></h3><p>在第 5 集短片中，我們將到太空並體驗一下沒有 Linux 的世界對太空探索的影響。這就像是一場瘋狂的騎行。在短片的最後，我們最終還是會見到沒有 Linux 的世界裏的 Linus。貫穿整個短片系列，裏邊已經給出關於結局的線索，我在這就不能給太多提示了，因為還有好多人在找線索比賽中繼續尋找着。並且我也不能給你們説出關於結局短片的上映日期。你們要自己跟進 #WorldWithoutLinux 主題帖來獲取更多信息。</p><h3 id="你可給一些關於第-4-集短片相關線索的提示嗎" tabindex="-1">你可給一些關於第 4 集短片相關線索的提示嗎？ <a class="header-anchor" href="#你可給一些關於第-4-集短片相關線索的提示嗎" aria-label="Permalink to “你可給一些關於第 4 集短片相關線索的提示嗎？”">​</a></h3><p>在該短片中有另外一個關於免費漢堡餐廳（Free Burger Restaurant）的線索。在那個沒有 Linux 的世界裏，Linux 最後還是以一種很隱秘的方式出現了，可以説，就像是以另一種語言來解讀 Linux。當然，這只是為了好玩，String 也以另外一個模樣出現。</p><h3 id="那麼-該系列短片達到你所想要的效果了嗎" tabindex="-1">那麼，該系列短片達到你所想要的效果了嗎？ <a class="header-anchor" href="#那麼-該系列短片達到你所想要的效果了嗎" aria-label="Permalink to “那麼，該系列短片達到你所想要的效果了嗎？”">​</a></h3><p>是的，達到了。我們很高興看到人們分享並參與到這些故事中去。我們希望向那些可能不知道 Linux 的人傳達更多關於 Linux 的故事並瞭解到 Linux 在當今世界中是無處不在的。全部的短片就是為了把這些關於 Linux 的真相推廣給大家，並感謝那些全球性社區的開發者和公司對 Linux 的支持，Linux 使得一切成為可能。</p><hr>',14)),o("p",null,[n[13]||(n[13]=i("via: ",-1)),a(t,{href:"http://thevarguy.com/open-source-application-software-companies/linux-foundation-explains-world-without-linux-and-open-so"},{default:u(()=>[...n[12]||(n[12]=[i("http://thevarguy.com/open-source-application-software-companies/linux-foundation-explains-world-without-linux-and-open-so",-1)])]),_:1})]),o("p",null,[n[17]||(n[17]=i("作者：",-1)),a(t,{href:"http://thevarguy.com/author/christopher-tozzi"},{default:u(()=>[...n[14]||(n[14]=[i("Christopher Tozzi",-1)])]),_:1}),n[18]||(n[18]=i(" 譯者：",-1)),a(t,{href:"https://github.com/GHLandy"},{default:u(()=>[...n[15]||(n[15]=[i("GHLandy",-1)])]),_:1}),n[19]||(n[19]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:u(()=>[...n[16]||(n[16]=[i("wxy",-1)])]),_:1})]),o("p",null,[n[22]||(n[22]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[20]||(n[20]=[i("LCTT",-1)])]),_:1}),n[23]||(n[23]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:u(()=>[...n[21]||(n[21]=[i("Linux中國",-1)])]),_:1}),n[24]||(n[24]=i(" 榮譽推出",-1))])])}const b=e(p,[["render",d]]);export{S as __pageData,b as default};
